r=public.save_business_settings(s,0,config);
if r->'settings'->'corrections'->>'recentDays'<>'14' or r->'settings'->'pageAccess'->'2' ? 'Sale Adjustments' then raise exception 'Dynamic settings not saved';end if;
rejected=false;begin perform public.save_business_settings(s,1,jsonb_set(config,'{corrections,recentDays}','0'));exception when others then rejected=true;end;if not rejected then raise exception 'Invalid correction window accepted';end if;
rejected=false;begin perform public.save_business_settings(s,1,jsonb_set(config,'{pageAccess,1}',(config->'pageAccess'->'1')||'"Conflict Inbox"'::jsonb));exception when others then rejected=true;end;if not rejected then raise exception 'Cashier conflict access accepted';end if;
perform set_config('request.jwt.claim.sub',current_setting('test.adjust_other'),true);
rejected=false;begin perform public.apply_supervised_event(s,jsonb_build_object('id',gen_random_uuid(),'kind','sale.corrected','data','{}'::jsonb));exception when others then if sqlerrm<>'Page access denied' then raise;end if;rejected=true;end;if not rejected then raise exception 'Disabled correction page still approved via API';end if;
perform set_config('request.jwt.claim.sub',current_setting('test.adjust_cashier'),true);
rejected=false;begin perform public.save_business_settings(s,1,config);exception when others then rejected=true;end;if not rejected then raise exception 'Cashier changed access settings';end if;
end;$$;reset role;rollback;
